"""生成报告用界面设计稿；不实现业务、不访问产品代码。"""
from pathlib import Path
import html
O=Path(__file__).resolve().parents[1]/'final/视觉整合版';O.mkdir(exist_ok=True)
CSS='''*{box-sizing:border-box}body{margin:0;background:#f4f6f2;color:#20352d;font:18px/1.55 'Microsoft YaHei',sans-serif}button,input{font:inherit}button{cursor:pointer;border:0;border-radius:9px;padding:12px 20px;background:#1e604d;color:white}button.alt{background:#edf2e9;color:#234e3f}small{font-size:14px;color:#647469}.app{display:grid;grid-template-columns:186px 1fr;height:820px;width:1200px}.rail{background:#fff;border-right:1px solid #e0e6de;padding:30px 18px;display:flex;flex-direction:column}.brand{font:32px Georgia;color:#1c5f4d;letter-spacing:-1px}.tag{font-size:12px;margin:0 0 38px;color:#768175}.nav{padding:12px 15px;margin:3px 0;border-radius:8px;font-size:16px;color:#607163}.nav.on{background:#e5eddd;color:#214f3d;font-weight:700}.railfoot{margin-top:auto;border-top:1px solid #dce4da;padding-top:18px;font-size:13px}.main{padding:27px 38px;overflow:hidden}.top{display:flex;justify-content:space-between;font-size:14px;color:#617064;margin-bottom:22px}.avatar{display:inline-flex;width:27px;height:27px;border-radius:50%;background:#d9e7c6;align-items:center;justify-content:center;color:#305b43}h1{font:36px/1.3 SimSun,serif;margin:10px 0 13px;font-weight:bold;letter-spacing:1px}h2{font-size:22px;margin:0 0 16px}h3{font-size:19px;margin:0 0 10px}p{margin:8px 0 14px}.muted{color:#6b776b}.eyebrow{font-size:13px;color:#5f765e;margin-bottom:12px}.paper{background:white;border:1px solid #e0e5db;border-radius:14px;padding:23px}.grid{display:grid;grid-template-columns:1.5fr 1fr;gap:22px}.cols{display:grid;grid-template-columns:1fr 1fr;gap:18px}.row{display:flex;align-items:center;justify-content:space-between;gap:15px}.chip{display:inline-block;padding:5px 10px;border-radius:5px;background:#edf2e5;font-size:13px;color:#466137}.warn{background:#fff0dc;color:#875b20}.line{border-top:1px solid #e4e8df;margin:16px 0}.label{font-size:14px;color:#647368}.field{background:#f6f8f3;border:1px solid #d9e1d4;border-radius:8px;padding:13px 16px;color:#263b2f}.accent{background:#b24e32}.hero{position:relative;background:#e7eedf;border-radius:18px;min-height:310px;padding:26px 28px;overflow:hidden}.hero h1{max-width:400px}.hero p{max-width:375px}.hero .plate{position:absolute;right:-18px;top:30px;width:310px}.input{background:white;border:1px solid #ced9c7;padding:17px 20px;border-radius:12px;margin-top:20px;display:flex;justify-content:space-between;align-items:center}.tabs{display:flex;gap:24px;border-bottom:1px solid #dbe2d5;margin:23px 0 20px;padding-bottom:12px;font-size:16px}.tabs b{color:#9b442c}.table{width:100%;border-collapse:collapse;font-size:16px}.table th{font-weight:400;color:#6c796d;font-size:13px;text-align:left;border-bottom:1px solid #dce3d7;padding:10px}.table td{padding:14px 10px;border-bottom:1px solid #edf0e9}.large{font:38px Georgia;color:#23573e}.stat{background:#edf2e6;padding:16px 20px;border-radius:10px}.note{font-size:14px;border-left:3px solid #d3aa5d;padding-left:12px;color:#725c35}.footer{font-size:12px;color:#7e877c;margin-top:20px}.mealname{font:28px SimSun;line-height:1.4}.date{color:#a45d37;font-size:14px}.timeline{border-left:2px solid #d5dfcc;margin:15px 0 0 8px;padding-left:20px}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:#6c8c50;margin-right:8px}.bar{height:9px;border-radius:7px;background:#e7eddf;margin:12px 0}.bar i{display:block;height:100%;border-radius:7px;background:#66854b}.options{display:flex;gap:10px;flex-wrap:wrap}.option{border:1px solid #d7dfd0;border-radius:8px;padding:13px 18px}.option.sel{border-color:#517742;background:#e7efde}.check{font-size:17px;color:#436c36}.portrait{width:86px;height:86px;border-radius:50%;background:#e5eddb;display:grid;place-items:center;font-size:30px;color:#577340}.switch{width:37px;height:21px;border-radius:15px;background:#497343;display:inline-block;position:relative}.switch:after{content:'';background:white;width:15px;height:15px;border-radius:50%;position:absolute;right:3px;top:3px}.mini{font-size:14px}'''
PLATE='''<svg class="plate" viewBox="0 0 360 360" xmlns="http://www.w3.org/2000/svg"><circle cx="180" cy="180" r="166" fill="#d1dbc5"/><circle cx="175" cy="172" r="154" fill="#fffdf8"/><circle cx="175" cy="172" r="133" fill="#f3efdf"/><path d="M65 183Q60 87 150 64L163 179Z" fill="#7a9b59"/><g fill="#315b38"><ellipse cx="100" cy="111" rx="31" ry="20" transform="rotate(-32 100 111)"/><ellipse cx="120" cy="145" rx="39" ry="21" transform="rotate(-48 120 145)"/><ellipse cx="91" cy="162" rx="30" ry="18" transform="rotate(17 91 162)"/></g><path d="M181 68Q286 67 298 167L181 177Z" fill="#d9bd87"/><g stroke="#f9e7c1" stroke-width="5"><path d="M199 90l-7 28m29-25l-8 30m28-17l-9 30m32-7l-9 24m-64-2l20 4"/></g><g fill="#c97b4c"><rect x="118" y="211" width="62" height="37" rx="12" transform="rotate(-15 150 230)"/><rect x="178" y="220" width="65" height="38" rx="12" transform="rotate(18 210 239)"/></g><g fill="#e49468"><circle cx="220" cy="186" r="20"/><circle cx="259" cy="195" r="19"/></g><path d="M103 237q34 31 58 17" fill="none" stroke="#597b43" stroke-width="7" stroke-linecap="round"/></svg>'''
def box(title,body):return f'<section class="paper"><h2>{title}</h2>{body}</section>'
def field(label,value):return f'<div class="label">{label}</div><div class="field">{value}</div>'
def table(heads,rows):return '<table class="table"><tr>'+''.join('<th>'+x+'</th>' for x in heads)+'</tr>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</table>'
def wrap(key,title,body,active):
 nav=['今日一餐','食品资料','计划与准备','食材库存','实际记录','阶段回顾','设置']
 s=f'<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><style>{CSS}</style><body><div class="app"><aside class="rail"><div class="brand">DietLens</div><p class="tag">好好吃饭，慢慢改变</p>'+''.join(f'<div class="nav {"on" if x==active else ""}">{x}</div>' for x in nav)+'<div class="railfoot">一个小改变<br>从眼前这一餐开始</div></aside><main class="main"><div class="top"><span>'+title+'</span><span>11月17日　周二　 <span class="avatar">我</span></span></div>'+body+'<div class="footer">交互设计稿 · 示例资料　｜　实际记录、采纳与执行分别确认</div></main></div></body></html>'
 (O/(key+'.html')).write_text(s,encoding='utf-8')
wrap('care','今日一餐',f'''<div class="hero"><div class="eyebrow">先照顾眼前这一餐</div><h1>吃得从容一点，<br>改变也可以小一点。</h1><p class="muted">不必重新安排一整天。告诉我这一餐，<br>一起找一个现在能做到的选择。</p><span class="chip">已带入：少糖目标</span> <span class="chip">每餐预算 20 元</span>{PLATE}</div><div class="input"><span>午餐吃了牛肉面，帮我想想晚餐怎么安排</span><button>整理这句话</button></div><div class="row mini" style="margin:10px 0 23px"><span class="muted">先整理成草稿，核对后再保存。</span><span>手动填写　 /　 可选图片</span></div><div class="cols">{box('这句话，分成两件事','<span class="chip">待核对记录</span><p>午餐 · 牛肉面，份量待确认</p><small>保存记录后仍可单独取消晚餐建议。</small>')}{box('只迈出一个小步','<span class="chip">尚未采纳</span><p>晚餐优先找低准备负担的选项</p><small>先确认时间和可获得的食物。</small>')}</div>''','今日一餐')
wrap('food','食品资料 / 核对与比较','''<h1>看清楚，再做选择。</h1><p class="muted">来源、口径和未知项，都放在眼前。</p><div class="tabs"><b>识别食品</b><span>比较食品</span><span>选择菜单</span></div><div class="grid">'''+box('核对这瓶燕麦饮品','''<div class="row"><span class="chip warn">推荐前需要核对</span><small>包装商品 · 250 mL</small></div><div class="line"></div>'''+table(['字段','当前资料','来源'],[['配料','燕麦、水','标签照片'],['过敏原','尚未核实','来源未提供'],['能量','42 / 55 kcal/100mL','两个来源冲突'],['价格','未知','尚未填写']])+'''<p class="note">当前档案含牛奶过敏。过敏原未核实前，停止相关主动推荐。</p><button>补充标签信息</button> <button class="alt">继续浏览</button>''')+box('每条判断，都有出处','''<div class="eyebrow">本次用途：查看食品资料</div><h3>可以浏览，暂不能推荐</h3><p class="muted">营养冲突不取平均，配料缺失不由模型补全。</p><div class="line"></div><p><span class="dot"></span>本次包装标签</p><small>用户提供 · 11月17日核对</small><p><span class="dot"></span>外部商品资料</p><small>保留商品标识与抓取时间</small><div class="line"></div><small>上传图片前单独确认接收方、用途和保存期限；也可手动填写。</small>''')+'</div>','食品资料')
wrap('plan','计划与准备 / 有效餐次','''<div class="row"><div><h1>把下一餐，安排得刚好。</h1><p class="muted">计划是未来安排，吃过之后再记录实际。</p></div><button>新增计划</button></div><div class="tabs"><b>当前安排</b><span>备选计划</span><span>单计划清单</span><span>跨计划采购预览</span></div><div class="grid">'''+box('明天的午餐','''<div class="row"><span class="date">11月18日 · 午餐</span><span class="chip">当前有效</span></div><h1 class="mealname">鸡肉饭 · 清炒时蔬</h1><p>2 人份　 /　 已核对餐次预算</p>'''+PLATE.replace('class="plate"','style="width:225px;height:200px;display:block;margin:0 auto"')+'''<small>鸡肉 300g · 青菜 200g · 鸡蛋 2个</small><div class="line"></div><button>编辑并核对变化</button> <button class="alt">预填实际记录</button>''')+box('本次变更，只影响选中餐次','''<div class="eyebrow">准备替换：11月18日午餐</div><p>原安排：番茄鸡蛋面</p><p>新安排：鸡肉饭与时蔬</p><div class="line"></div><p class="check">其他日期与餐次保持原安排</p><p class="note">相关清单需重新核对。已购和手工调整保留，差异由你确认。</p><div class="options"><div class="option sel">替换这一餐</div><div class="option">仅存备选</div></div><div class="line"></div><small>保存前重新检查食品证据、预算和最新版本。</small>''')+'</div>','计划与准备')
wrap('inventory','食材库存 / 共享余量','''<div class="row"><div><h1>知道手边有什么，<br>下一步轻松一点。</h1><p class="muted">采购进度和库存余量，各自核对。</p></div><button>确认库存调整</button></div>'''+box('已确认库存',table(['食材与批次','数量','有效期','状态'],[['鸡肉 · 批次一','100 g','11月18日','<span class="chip">优先用于适用日期</span>'],['鸡肉 · 批次二','200 g','11月25日','<span class="chip">已核对</span>'],['鸡蛋','2 个','未填写','<span class="chip warn">未来可用性待核对</span>'],['青菜','少量','未填写','数值差额未知']]))+'''<div class="cols" style="margin-top:20px">'''+box('跨计划只读预览','<p>18日需鸡肉 200g，20日需 100g。</p><p class="check">按餐次与有效期估算：当前数量可覆盖。</p><small>只估算，不预占、不自动扣库存。</small>')+box('每次调整，都先看结果','<p>入库、用量或删除由你单独确认。</p><small>数量未知或单位不可比时，先核对；扣减不能超过当前库存。</small>')+'</div>','食材库存')
wrap('meal','实际记录 / 一餐多种食物','''<h1>吃过什么，如实记下来。</h1><p class="muted">一份用餐记录可以有多种食物；不知道的份量，留作未知。</p><div class="grid">'''+box('午餐记录草稿','<div class="row"><span class="chip">尚未保存</span><span>11月17日 · 12:20</span></div>'+table(['实际食物','本人份量','来源'],[['番茄鸡蛋面','1 碗','用户自述'],['无糖茶','300 mL','用户自述'],['苹果','未知','用户自述']])+'''<p class="mini">＋ 添加一种食物　　修改日期 / 餐次</p><div class="line"></div><button>确认保存这一餐</button> <button class="alt">取消草稿</button>''')+box('核对后再成为记录','''<h3>只确认本人的实际用餐</h3><p class="muted">计划预填只是起点。可以删改，也可以取消。</p><div class="line"></div><p class="check">不自动扣减食材库存</p><p class="check">不把行动写成已完成</p><p class="check">未知份量不按零计算</p><div class="line"></div><small>保存后可修正原记录；同一午餐的多次用餐按各自事实保存。</small>''')+'</div>','实际记录')
wrap('action','今日一餐 / 一个微行动','''<div class="row"><div><h1>主餐照旧，配饮换白水。</h1><p class="muted">给这一餐留一个容易做到的小改变。</p></div><span class="chip">平替 · 尚未采纳</span></div><div class="grid">'''+box('点午餐饮品时，选择白水','''<div style="height:130px;display:flex;justify-content:center;align-items:center"><svg width="110" height="140" viewBox="0 0 100 140"><path d="M22 20h56l-8 100H30Z" fill="#dce9e0" stroke="#32664e" stroke-width="2"/><path d="M28 60h44l-5 52H33Z" fill="#9cc2bd"/><path d="M36 35h27" stroke="white" stroke-width="5"/></svg></div><div class="row"><span>努力量：低</span><span>额外费用：0 元</span></div><div class="line"></div><p>符合已确认的少糖目标，白水当前可获得；不增加本次餐费。</p><small>其他饮品配料待核对，暂未进入主候选。</small>''')+box('确认这次尝试的时间','''<div class="label">行动窗口，可修改</div><div class="field">11月18日 11:00 — 14:00</div><p class="mini muted">采纳只表示愿意试一试，执行结果之后再说。</p><div class="options"><div class="option">修改时间</div><div class="option">换一个</div><div class="option">跳过</div></div><div class="line"></div><button>确认采纳</button><p class="label" style="margin-top:24px">稍后反馈</p><div class="options"><div class="option">完成</div><div class="option">部分完成</div><div class="option">未完成</div></div><small>执行日期可修改，照片和笔记可选。</small>''')+'</div>','今日一餐')
wrap('workbench','阶段回顾 / 已记录范围','''<div class="row"><div><h1>回头看看，再选下一步。</h1><p class="muted">11月9日—15日　 /　 已确认预期餐次：10</p></div><button class="alt">修改预期餐次</button></div><div class="cols">'''+box('手边的余地','<p>鸡肉、鸡蛋已有数量依据</p><small>青菜差额未知，可进入库存核对。</small>')+box('日常的节奏','<div class="row"><span class="large">6 / 10</span><span class="chip">记录覆盖 60%</span></div><div class="bar"><i style="width:60%"></i></div><small>只描述已记录范围；没有记录不等于没吃。</small>')+box('小行动的尝试','<div class="row"><span>本周采纳</span><b>6 次</b></div><div class="row"><span>明确换候选 / 修改</span><b>2 / 1 次</b></div><small>采纳与更换，不计作执行完成。</small>')+box('执行与调整','<div class="row"><span>已结束窗口的反馈覆盖</span><b>5 / 8</b></div><div class="row"><span>其中自述完成比例</span><b>3 / 5</b></div><small>另有3次未知，仍可补充迟到反馈。</small>')+'''</div><div class="paper" style="margin-top:20px;border-left:5px solid #ba714e"><div class="row"><div><h3>这两次晚餐，都提到时间困难。</h3><small>来源：11日、12日晚餐及对应行动反馈。是否需要减少准备步骤？</small></div><button>核对并带入下一次</button></div></div>''','阶段回顾')
wrap('settings','设置 / 你的资料与选择','''<h1>资料由你掌握，节奏也是。</h1><p class="muted">按用途授权，随时调整或关闭。</p><div class="grid">'''+box('个人条件与可选校准','''<div class="row"><div class="portrait">我</div><span class="chip">已确认档案</span></div><div class="line"></div><p>目标　减少含糖饮品</p><p>预算　每人每餐 20 元</p><p>硬约束　按已确认档案核对</p><div class="line"></div><h3>三道情境题，按需回答</h3><p class="muted mini">可以全跳过、逐题修改或删除；不影响核心功能。</p><button class="alt">管理校准回答</button>''')+box('授权与恢复','''<div class="row"><span>历史分析</span><span class="switch"></span></div><div class="line"></div><div class="row"><span>提醒订阅</span><span>未开启</span></div><p class="muted mini">未响应不算失败，主动请求始终可用。</p><div class="line"></div><h3>继续上次的任务</h3><p>晚餐候选 · 等待核对时间</p><small>恢复后检查最新授权、条件与版本。</small><p><button class="alt">继续核对</button></p><div class="line"></div><span class="mini">导出资料　 /　 删除资料</span>''')+'</div>','设置')
(O/'视觉方向.md').write_text('''# 视觉方向与修改范围

以组员精简润色稿为正文基础，保留七个领域服务、有效餐次、食品三类判断、临时候选与正式行动、四类回顾和复合任务的语义。仅对发现的歧义作局部澄清。

界面采用“餐盘里的一个小改变”：白与浅食材绿为底，森林绿承担操作，陶土色保留温暖识别；餐盘示意只在首页与计划帮助理解一餐组成。常规文字采用清晰无衬线字体，重点标题采用宋体。报告正文使用宋体黑字，界面保留彩色。图稿为目标交互设计，不宣称产品已实现。

不采用健康评分、惩罚性打卡或夸大健康效果。各页面保留来源、未知项、确认与取消；反馈指标来自组员稿的同一示例队列。
''',encoding='utf-8')
for key,style in {
 'inventory':'.main{padding-top:20px}.main h1{font-size:32px}.main .paper{padding:18px}.main .table td{padding:10px}.main p{margin-bottom:10px}',
 'plan':'.main .paper{padding:18px}.main h1{font-size:33px}.main svg{height:150px!important}.main .line{margin:12px 0}',
 'food':'.main .paper{padding:20px}'
}.items():
 path=O/(key+'.html');text=path.read_text(encoding='utf-8').replace('</style>',style+'</style>');path.write_text(text,encoding='utf-8')
path=O/'action.html';path.write_text(path.read_text(encoding='utf-8').replace('稍后反馈</p>','采纳后开放：执行反馈</p>'),encoding='utf-8')
print('已生成八个彩色界面设计稿。')
